import java.util.HashMap;
import java.util.Map;

public class Ex06L1CacheScope {

    static class Database {
        int queries = 0;
        final Map<String, String> rows = new HashMap<String, String>();

        Database() {
            rows.put("1", "tom");
            rows.put("2", "amy");
        }

        String query(String sql) {
            queries++;
            String id = sql.substring(sql.lastIndexOf("= ") + 2).trim();
            return rows.get(id);
        }
    }

    // 一级缓存 = SqlSession 级本地缓存
    static class SqlSession {
        final Database db;
        final Map<String, String> localCache = new HashMap<String, String>();
        int l1Hits = 0;

        SqlSession(Database db) {
            this.db = db;
        }

        String selectOne(String sql) {
            if (localCache.containsKey(sql)) {
                l1Hits++;
                return localCache.get(sql);
            }
            String v = db.query(sql);
            localCache.put(sql, v);
            return v;
        }

        // 语句上 flushCache="true"：每次都绕过一级缓存
        String selectWithFlushCache(String sql) {
            localCache.remove(sql);
            return db.query(sql);
        }

        // 任何增删改都会清空本会话的一级缓存
        void update(String sql) {
            db.queries++;
            localCache.clear();
        }

        void close() {
            localCache.clear();
        }
    }

    public static void main(String[] args) {
        Database db = new Database();
        String sql = "SELECT name FROM t_user WHERE id = 1";

        SqlSession s1 = new SqlSession(db);
        s1.selectOne(sql);
        System.out.println("s1 select#1      : dbQueries=" + db.queries + " l1Hits=" + s1.l1Hits);
        s1.selectOne(sql);
        System.out.println("s1 select#2      : dbQueries=" + db.queries + " l1Hits=" + s1.l1Hits);
        s1.close();

        SqlSession s2 = new SqlSession(db);
        s2.selectOne(sql);
        System.out.println("s2 select#1      : dbQueries=" + db.queries + " l1Hits=" + s2.l1Hits);
        s2.update("UPDATE t_user SET name = 'z' WHERE id = 1");
        s2.selectOne(sql);
        System.out.println("s2 after update  : dbQueries=" + db.queries + " l1Hits=" + s2.l1Hits);

        SqlSession s3 = new SqlSession(db);
        s3.selectWithFlushCache(sql);
        s3.selectWithFlushCache(sql);
        System.out.println("s3 flushCache x2 : dbQueries=" + db.queries + " l1Hits=" + s3.l1Hits);

        SqlSession s4 = new SqlSession(db);
        System.out.println("s4 select#1      : " + s4.selectOne(sql));
        db.rows.put("1", "ZED");
        System.out.println("direct db write  : rows[1]=" + db.rows.get("1"));
        String again = s4.selectOne(sql);
        System.out.println("s4 select#2(L1)  : " + again);
        System.out.println("db row now       : " + db.rows.get("1"));
        System.out.println("stale read       : " + (!again.equals(db.rows.get("1"))));
        System.out.println("cross session l1 : " + (s2.l1Hits == 0));
    }
}
